from collections import Counter
def f(inp):
    H,W=len(inp),len(inp[0])
    cnt=Counter(x for r in inp for x in r)
    bg=cnt.most_common(1)[0][0]
    pts=[(i,j) for i in range(H) for j in range(W) if inp[i][j]!=bg and inp[i][j]!=0]
    r0=min(i for i,j in pts); r1=max(i for i,j in pts)
    c0=min(j for i,j in pts); c1=max(j for i,j in pts)
    pat=[[inp[i][j] for j in range(c0,c1+1)] for i in range(r0,r1+1)]
    pgh,pgw=len(pat),len(pat[0])
    best=None
    for i in range(H-pgh+1):
        for j in range(W-pgw+1):
            if all(inp[i+a][j+b]==0 for a in range(pgh) for b in range(pgw)):
                if best is None or (pgh*pgw)>=(best[2]):
                    best=(i,j,pgh*pgw)
    i,j=best[0],best[1]
    out=[r[:] for r in inp]
    for a in range(pgh):
        for b in range(pgw):
            out[i+a][j+b]=pat[a][b]
    return out
